type Dial = typeof TILE_DIAL;

type GlassShot = {
  w: number;
  h: number;
  map: string;
  specular: string;
  specularDark: string;
};

const LUT_SIZE = 128;
const LIGHT_SPREAD = 1.08;
const DIFFUSE_SPREAD = LIGHT_SPREAD * 0.65;

type SurfaceLUTs = { mag: Float32Array; slope: Float32Array };
let squircleLut: SurfaceLUTs | null = null;

function sat(x: number): number {
  return x < 0 ? 0 : x > 1 ? 1 : x;
}

/** Squircle slab: Snell bend along the bezel. Port of surfaceLUTs('squircle'). */
function surfaceLUTs(): SurfaceLUTs {
  if (squircleLut) return squircleLut;
  const mag = new Float32Array(LUT_SIZE);
  const slope = new Float32Array(LUT_SIZE);
  const n = 1.5;
  const thickness = 0.6;
  const heightAt = (t: number): number => Math.pow(1 - Math.pow(1 - t, 4), 0.25);
  const eps = 1 / 1024;
  let max = 0;
  for (let i = 0; i < LUT_SIZE; i++) {
    const t = Math.max(i / (LUT_SIZE - 1), eps);
    const hi = Math.min(t + eps, 1);
    const lo = Math.max(t - eps, 0);
    slope[i] = ((heightAt(hi) - heightAt(lo)) / (hi - lo)) * thickness;
    const thetaI = Math.atan(Math.abs(slope[i]));
    const delta = thetaI - Math.asin(Math.sin(thetaI) / n);
    mag[i] = heightAt(t) * thickness * Math.tan(delta);
    max = Math.max(max, mag[i]);
  }
  if (max > 0) {
    for (let i = 0; i < LUT_SIZE; i++) mag[i] /= max;
  }
  squircleLut = { mag, slope };
  return squircleLut;
}

type SurfaceField = { sd: number; nx: number; ny: number };

/**
 * Rounded-rect outline SDF. The corner arc matches CSS border-radius.
 * A squircle plan against that radius left a second curve at the corner.
 */
function surfaceField(px: number, py: number, bx: number, by: number, r: number, out: SurfaceField): void {
  const qx = Math.abs(px) - bx;
  const qy = Math.abs(py) - by;
  const ox = Math.max(qx, 0);
  const oy = Math.max(qy, 0);
  out.sd = Math.hypot(ox, oy) + Math.min(Math.max(qx, qy), 0) - r;
  if (qx > 0 && qy > 0) {
    const len = Math.hypot(qx, qy) || 1;
    out.nx = (Math.sign(px) * qx) / len;
    out.ny = (Math.sign(py) * qy) / len;
  } else if (qx > qy) {
    out.nx = Math.sign(px);
    out.ny = 0;
  } else {
    out.nx = 0;
    out.ny = Math.sign(py);
  }
}

const IMAGE_CACHE_MAX = 48;
const imageCache = new Map<string, { map: string; specular: string; specularDark: string }>();

function cacheGet(key: string): { map: string; specular: string; specularDark: string } | undefined {
  const hit = imageCache.get(key);
  if (!hit) return undefined;
  imageCache.delete(key);
  imageCache.set(key, hit);
  return hit;
}

/**
 * Displacement map (R = x, B = y, 128 = rest) plus a baked specular rim.
 * Port of glassImages. Large maps are half-resolution; the rim stays full-res.
 */
function glassImages(
  fullW: number,
  fullH: number,
  fullRadius: number,
  fullBezel: number,
): { map: string; specular: string; specularDark: string } | null {
  if (typeof document === "undefined") return null;
  const key = `${fullW}x${fullH}r${fullRadius}b${fullBezel}`;
  const cached = cacheGet(key);
  if (cached) return cached;
  try {
    const scale = fullW * fullH > 32000 ? 0.5 : 1;
    const w = Math.ceil(fullW * scale);
    const h = Math.ceil(fullH * scale);
    const radius = fullRadius * scale;
    // Stay inside the corner. A bezel past the radius pinches a second edge.
    const safeBezel = Math.min(fullBezel, Math.max(1, fullRadius * 0.85));
    const bezel = Math.max(1, safeBezel * scale);
    const canvas = document.createElement("canvas");
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext("2d");
    if (!ctx) return null;
    const image = ctx.createImageData(w, h);
    const data = image.data;
    const { mag: lut } = surfaceLUTs();
    const field: SurfaceField = { sd: 0, nx: 0, ny: 0 };
    const r = Math.min(radius, w / 2, h / 2);
    const bx = w / 2 - r;
    const by = h / 2 - r;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const px = x + 0.5 - w / 2;
        const py = y + 0.5 - h / 2;
        surfaceField(px, py, bx, by, r, field);
        const depth = -field.sd;
        const d = depth / bezel;
        const inRim = d < 1 && d >= 0;
        const idx = inRim ? Math.min(Math.round(d * (LUT_SIZE - 1)), LUT_SIZE - 1) : 0;
        const mag = inRim ? lut[idx] : 0;
        const i = (y * w + x) * 4;
        data[i] = Math.round(128 - field.nx * mag * 127);
        data[i + 1] = 128;
        data[i + 2] = Math.round(128 - field.ny * mag * 127);
        data[i + 3] = 255;
      }
    }
    ctx.putImageData(image, 0, 0);

    const specW = fullW;
    const specH = fullH;
    const specR = Math.min(fullRadius, specW / 2, specH / 2);
    const specBx = specW / 2 - specR;
    const specBy = specH / 2 - specR;
    const lightCanvas = document.createElement("canvas");
    const darkCanvas = document.createElement("canvas");
    lightCanvas.width = specW;
    lightCanvas.height = specH;
    darkCanvas.width = specW;
    darkCanvas.height = specH;
    const lightCtx = lightCanvas.getContext("2d");
    const darkCtx = darkCanvas.getContext("2d");
    if (!lightCtx || !darkCtx) return null;
    const lightImage = lightCtx.createImageData(specW, specH);
    const darkImage = darkCtx.createImageData(specW, specH);
    const cosLight = Math.cos(LIGHT_SPREAD);
    const cosDiffuse = Math.cos(DIFFUSE_SPREAD);
    // Highlight feathers inward across the bezel on this same outline.
    // No second dark stroke — that read as a stepped rim.
    const lip = Math.max(5, safeBezel * 0.5);
    const reach = 4 + safeBezel * 0.24;
    const compose = (
      out: Uint8ClampedArray,
      i: number,
      specAmount: number,
      diffuse: number,
      shadeBase: number,
      specScale: number,
      diffuseScale: number,
      shadeStrength: number,
    ): void => {
      const highlight = sat(specAmount * specScale + diffuse * diffuseScale);
      const shade = shadeBase * shadeStrength;
      const alpha = highlight + shade * (1 - highlight);
      if (alpha <= 0) return;
      const value = Math.min((specScale * highlight) / alpha, 1);
      const v = Math.round(value * 255);
      out[i] = v;
      out[i + 1] = v;
      out[i + 2] = v;
      out[i + 3] = Math.round(Math.min(alpha, 1) * 255);
    };
    for (let y = 0; y < specH; y++) {
      for (let x = 0; x < specW; x++) {
        const px = x + 0.5 - specW / 2;
        const py = y + 0.5 - specH / 2;
        surfaceField(px, py, specBx, specBy, specR, field);
        const sd = field.sd;
        if (sd > 1 || sd < -(reach + 1)) continue;
        const coverage = sat(0.42 - sd);
        const vertical = Math.abs(field.ny);
        const directional = Math.pow(sat((vertical - cosLight) / (1 - cosLight)), 1.15);
        const diffuseDir = Math.pow(sat((vertical - cosDiffuse) / (1 - cosDiffuse)), 1.15);
        const into = sat(-sd / lip);
        // One lip. A dark hairline beside this feather reads as a second stroke.
        // The edge term keeps the sides as crisp as the crown, still on this outline.
        const feather = sat(0.38 - sd) * Math.pow(1 - into, 2.15);
        const edge = sat(0.72 - sd) * Math.pow(1 - into, 2.45);
        let specAmount = directional * feather + edge * 0.82 * (1 - directional * 0.4);
        specAmount = specAmount / (1 + 0.2 * (1 - specAmount));
        const glow = 1 - sat(-sd / reach);
        const diffuse = diffuseDir * 0.2 * glow * glow * coverage;
        const i = (y * specW + x) * 4;
        compose(lightImage.data, i, specAmount, diffuse, 0, 1.04, 0.7, 0);
        compose(darkImage.data, i, specAmount, diffuse, 0, 1.14, 0.5, 0);
      }
    }
    lightCtx.putImageData(lightImage, 0, 0);
    darkCtx.putImageData(darkImage, 0, 0);
    const shot = {
      map: canvas.toDataURL(),
      specular: lightCanvas.toDataURL(),
      specularDark: darkCanvas.toDataURL(),
    };
    imageCache.set(key, shot);
    if (imageCache.size > IMAGE_CACHE_MAX) {
      const oldest = imageCache.keys().next().value;
      if (oldest) imageCache.delete(oldest);
    }
    return shot;
  } catch {
    return null;
  }
}

/** Tone curve from filterRegistry: lift shadows, roll highlights, spare the mids. */
function toneTable(frost: number): string {
  const toneLift = Math.round(180 * (1 - 0.45 * frost)) / 1000;
  const toneRoll = Math.round(140 * (1 - 0.45 * frost)) / 1000;
  const steps = 17;
  const samples: string[] = [];
  for (let i = 0; i < steps; i++) {
    const v = i / (steps - 1);
    const lifted = v + toneLift * (1 - v) ** 3;
    samples.push(String(Math.round((lifted - toneRoll * lifted ** 3) * 1000) / 1000));
  }
  return samples.join(" ");
}

let lensSeq = 0;

function GlassPane({
  kind,
  href,
  focused,
  onFocus,
  onBlur,
  contentStyle,
  children,
  name,
  frame,
}: {
  kind: "tile" | "chip";
  href: string;
  focused: boolean;
  onFocus: () => void;
  onBlur: () => void;
  contentStyle: CSSProperties;
  children: ReactNode;
  /** Accessible name. Icon chips have no visible words, so this carries the handle. */
  name?: string;
  /** Anchor box. Icon chips pass a fixed square so the pill dial becomes a circle. */
  frame?: CSSProperties;
}): JSX.Element {
  const look = useBillboardLook();
  const dark = look.dark;
  const dial: Dial = kind === "tile" ? TILE_DIAL : CHIP_DIAL;
  const ref = useRef<HTMLAnchorElement | null>(null);
  const idRef = useRef("");
  if (idRef.current.length === 0) {
    lensSeq += 1;
    idRef.current = `billboard-lens-${lensSeq}`;
  }
  const filterId = idRef.current;
  const [shot, setShot] = useState<GlassShot | null>(null);
  const [hovered, setHovered] = useState(false);
  const [pressed, setPressed] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let dead = false;
    const paint = (): void => {
      const w = Math.round(el.clientWidth);
      const h = Math.round(el.clientHeight);
      if (w < 2 || h < 2) return;
      const radius = dial.radius >= 999 ? Math.min(w, h) / 2 : dial.radius;
      const images = glassImages(w, h, radius, dial.bezel);
      if (!images || dead) return;
      setShot((prev) => (prev && prev.w === w && prev.h === h ? prev : { w, h, ...images }));
    };
    paint();
    const observer = new ResizeObserver((): void => {
      paint();
    });
    observer.observe(el);
    return (): void => {
      dead = true;
      observer.disconnect();
    };
  }, [dial]);

  const effectiveBlur = Math.round((dial.blur + dial.frost * 14) * 100) / 100;
  const frostFilter = `blur(${effectiveBlur}px) saturate(${dial.saturation})`;
  const tintOpacity = 0.25 + 0.75 * dial.frost;
  const radius = dial.radius >= 999 ? 999 : dial.radius;
  const tone = toneTable(dial.frost);
  const clip = `inset(0 round ${radius}px)`;
  const lift = kind === "tile" ? "-3px" : "-2px";
  const transform = pressed ? "translateY(0) scale(0.97)" : hovered ? `translateY(${lift}) scale(1)` : "translateY(0) scale(1)";
  const inkShadow = hovered ? (dark ? SOFT_SHADOW_HOVER_DARK : SOFT_SHADOW_HOVER_LIGHT) : dark ? SOFT_SHADOW_DARK : SOFT_SHADOW_LIGHT;
  const hotVars = {
    "--bb-ink-shadow": inkShadow,
  } as CSSProperties;
  const destination = href.trim();

  return (
    <a
      ref={ref}
      href={destination.length > 0 ? destination : undefined}
      target={destination.length > 0 ? "_blank" : undefined}
      rel={destination.length > 0 ? "noreferrer" : undefined}
      aria-label={name}
      title={name}
      onFocus={onFocus}
      onBlur={(): void => {
        setPressed(false);
        onBlur();
      }}
      onMouseEnter={(): void => setHovered(true)}
      onMouseLeave={(): void => setHovered(false)}
      onPointerDown={(event: PointerEvent<HTMLAnchorElement>): void => {
        setPressed(true);
        event.currentTarget.setPointerCapture(event.pointerId);
      }}
      onPointerUp={(event: PointerEvent<HTMLAnchorElement>): void => {
        setPressed(false);
        if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
      }}
      onPointerCancel={(): void => setPressed(false)}
      style={{
        position: "relative",
        isolation: "isolate",
        display: kind === "tile" ? "flex" : "inline-flex",
        width: kind === "tile" ? "100%" : undefined,
        flex: kind === "chip" ? "0 1 auto" : undefined,
        alignSelf: kind === "chip" ? "center" : undefined,
        overflow: kind === "chip" ? "hidden" : undefined,
        maxWidth: "100%",
        minWidth: 0,
        boxSizing: "border-box",
        borderRadius: radius,
        textDecoration: "none",
        color: look.glassInk,
        cursor: "pointer",
        transform,
        transformOrigin: "center",
        transition: `transform ${MOTION}, box-shadow ${MOTION}`,
        boxShadow: hovered && !pressed ? (dark ? ELEVATED_HOVER_DARK : ELEVATED_HOVER_LIGHT) : dark ? ELEVATED_DARK : ELEVATED_LIGHT,
        WebkitTapHighlightColor: CLEAR,
        outline: focused ? `2px solid ${look.accentFocus}` : FOCUS_NONE,
        outlineOffset: 3,
        ...hotVars,
        ...frame,
      }}
    >
      <div aria-hidden style={{ ...LAYER, zIndex: 0, overflow: "hidden", borderRadius: radius, clipPath: clip }}>
        <div style={{ ...LAYER, zIndex: 0, backdropFilter: frostFilter, WebkitBackdropFilter: frostFilter, background: CLEAR }} />
        {shot ? (
          <div style={{ ...LAYER, zIndex: 0, backdropFilter: `url(#${filterId})`, WebkitBackdropFilter: `url(#${filterId})`, background: CLEAR }} />
        ) : null}
        <div
          style={{
            ...LAYER,
            zIndex: 1,
            background: dark ? TINT_GRAD_DARK : TINT_GRAD_LIGHT,
            opacity: tintOpacity,
          }}
        />
        <div style={{ ...LAYER, zIndex: 1, background: dark ? MILK_DARK : MILK_LIGHT }} />
        {shot ? (
          <div
            style={{
              ...LAYER,
              zIndex: 2,
              backgroundImage: `url("${dark ? shot.specularDark : shot.specular}")`,
              backgroundSize: "100% 100%",
              opacity: dial.specular,
            }}
          />
        ) : null}
        <div style={{ ...LAYER, zIndex: 2, boxShadow: dark ? SHINE_DARK : SHINE_LIGHT }} />
        <div
          style={{
            ...LAYER,
            zIndex: 2,
            background: SHEEN,
            mixBlendMode: "screen",
            filter: SHEEN_BLUR,
            opacity: dark ? 0.36 : 0.14,
          }}
        />
        {shot ? (
          <svg aria-hidden width={0} height={0} style={{ position: "absolute", width: 0, height: 0, overflow: "hidden" }}>
            <filter
              id={filterId}
              filterUnits="userSpaceOnUse"
              x={0}
              y={0}
              width={shot.w}
              height={shot.h}
              colorInterpolationFilters="sRGB"
            >
              <feImage href={shot.map} xlinkHref={shot.map} x={0} y={0} width={shot.w} height={shot.h} preserveAspectRatio="none" result="map" />
              <feDisplacementMap in="SourceGraphic" in2="map" scale={dial.refraction} xChannelSelector="R" yChannelSelector="B" />
              <feComponentTransfer>
                <feFuncR type="table" tableValues={tone} />
                <feFuncG type="table" tableValues={tone} />
                <feFuncB type="table" tableValues={tone} />
              </feComponentTransfer>
            </filter>
          </svg>
        ) : null}
      </div>
      <div aria-hidden style={{ ...LAYER, zIndex: 3, background: HOVER_WASH, opacity: hovered ? 1 : 0, transition: `opacity ${MOTION}` }} />
      <div style={{ position: "relative", zIndex: 4, boxSizing: "border-box", minWidth: 0, ...contentStyle }}>{children}</div>
    </a>
  );
}

function atHandle(raw: string): string {
  const trimmed = raw.trim();
  if (trimmed.length === 0 || trimmed === "@") return "";
  return trimmed.startsWith("@") ? trimmed : `@${trimmed}`;
}

function filled(raw: string): string {
  return raw.trim();
}

/**
 * One emoji cluster: a flag, a keycap, or a pictograph with optional
 * variation selector, skin tone, flag tags, and ZWJ continuations.
 */
const EMOJI_CLUSTER =
  "(?:\\p{Regional_Indicator}{2}|[#*0-9]\\uFE0F?\\u20E3|\\p{Extended_Pictographic}(?:\\uFE0F|\\uFE0E)?\\p{Emoji_Modifier}?(?:[\\u{E0020}-\\u{E007E}]+\\u{E007F})?(?:\\u200D\\p{Extended_Pictographic}(?:\\uFE0F|\\uFE0E)?\\p{Emoji_Modifier}?(?:[\\u{E0020}-\\u{E007E}]+\\u{E007F})?)*)";
const TRAILING_EMOJI = new RegExp(`(?:\\s*${EMOJI_CLUSTER})+\\s*$`, "u");

function emojiClusters(run: string): string[] {
  return run.match(new RegExp(EMOJI_CLUSTER, "gu")) ?? [];
}

/**
 * Split a trailing emoji run off a display name. Each cluster is its own
 * inline box so a long name can still wrap, and a ZWJ sequence stays intact.
 * No trailing emoji returns an empty cluster list — the hero renders text only.
 */
function splitTrailingEmoji(raw: string): { text: string; clusters: readonly string[] } {
  const match = TRAILING_EMOJI.exec(raw);
  if (!match) return { text: raw.trim(), clusters: [] };
  const clusters = emojiClusters(match[0]);
  if (clusters.length === 0) return { text: raw.trim(), clusters: [] };
  return { text: raw.slice(0, match.index).trim(), clusters };
}

/** Half the hero. A lead margin of 0.32em of this glyph is ~0.16em of the h1. */
const HERO_EMOJI: CSSProperties = {
  display: "inline-block",
  fontSize: "0.5em",
  lineHeight: 1,
  verticalAlign: "middle",
  letterSpacing: "0",
  whiteSpace: "nowrap",
  textTransform: "none",
  maxWidth: "100%",
};

function heroEmojiStyle(index: number, hasText: boolean, color: string): CSSProperties {
  const marginLeft = index === 0 ? (hasText ? "0.32em" : "0") : "0.16em";
  return { ...HERO_EMOJI, marginLeft, color };
}

type Appearance = "dark" | "day";
type StageMood = "graphite" | "color";

type BillboardLook = {
  theme: ReturnType<typeof useGrokTheme>;
  appearance: Appearance;
  stage: StageMood;
  /** A dark device uses the dark glass stack. A light device uses the day stack. */
  dark: boolean;
  ink: string;
  /** Display name, tile titles, descriptions, and chips. The greyer see-through face. */
  glassInk: string;
  bg: string;
  well: string;
  accent: AccentName;
  /** Quiet stroke. Named accents may tint it. The bubble body stays neutral. */
  accentFocus: string;
};

/**
 * Host wins. A baked APPEARANCE of night, dark, day, or light is ignored, so
 * a filled page cannot stick on day while the phone is dark. Host light is
 * day. Host dark is the charcoal field. Night is not a deeper mode.
 */
function resolveAppearance(_raw: string, host: "light" | "dark"): Appearance {
  return host === "light" ? "day" : "dark";
}

function resolveStage(raw: string): StageMood {
  const value = raw.trim().toLowerCase();
  if (value === "color" || value === "colour") return "color";
  return "graphite";
}

function resolveAccent(raw: string): AccentName {
  const value = raw.trim().toLowerCase();
  if (value === "rose" || value === "sage" || value === "violet" || value === "amber" || value === "teal") return value;
  return "silver";
}

/** Silver keeps silver on dark and graphite on day. Named accents use a quiet stroke. */
function accentFocusColor(name: AccentName, dark: boolean): string {
  if (name === "silver") return dark ? SILVER : GRAPHITE;
  return ACCENT_FOCUS[name][dark ? "dark" : "light"];
}

/**
 * Appearance follows the opener. A filled APPEARANCE cannot override it.
 * Stage and accent still come from their fill tokens. Unset stage stays
 * graphite. Unset accent stays silver and leaves the device field alone.
 * A named accent tints that field and still tracks day or dark.
 */
function useBillboardLook(): BillboardLook {
  const theme = useGrokTheme();
  const appearance = resolveAppearance(APPEARANCE, theme.kind);
  const stage = resolveStage(STAGE);
  const dark = appearance === "dark";
  const accent = resolveAccent(ACCENT);
  // See-through body ink. theme.text.primary stays near-black in both kinds and stamps the glass.
  const ink = dark ? SEE_DARK : SEE_DAY;
  const glassInk = dark ? TILE_SEE_DARK : TILE_SEE_DAY;
  return {
    theme,
    appearance,
    stage,
    dark,
    ink,
    glassInk,
    bg: theme.bg.base,
    well: theme.fill.secondary,
    accent,
    accentFocus: accentFocusColor(accent, dark),
  };
}

function useFocusRing(): { focused: boolean; onFocus: () => void; onBlur: () => void } {
  const [focused, setFocused] = useState(false);
  return {
    focused,
    onFocus: (): void => setFocused(true),
    onBlur: (): void => setFocused(false),
  };
}

function iconWell(size: number, radius: number, look: BillboardLook): CSSProperties {
  return {
    width: size,
    height: size,
    flex: `0 0 ${size}px`,
    borderRadius: radius,
    overflow: "hidden",
    position: "relative",
    zIndex: 1,
    background: look.well,
    boxShadow: look.dark ? ICON_RING_DARK : ICON_RING_LIGHT,
  };
}

function avatarRing(look: BillboardLook): CSSProperties {
  return {
    width: AVATAR_SIZE,
    height: AVATAR_SIZE,
    flex: `0 0 ${AVATAR_SIZE}px`,
    borderRadius: 9999,
    overflow: "hidden",
    background: look.well,
    boxShadow: look.dark ? AVATAR_RING_DARK : AVATAR_RING_LIGHT,
  };
}

type DriftName = "a" | "b" | "c" | "d" | "bandA" | "bandB" | "flowA" | "flowB" | "flowC";

/**
 * Transform only, so the glass displacement maps are not rebuilt each frame.
 * The first keyframe is the resting pose (reduced motion, and the frame
 * before animate() starts). Durations are long on purpose.
 */
const DRIFT_FRAMES: Record<DriftName, [{ transform: string }, { transform: string }]> = {
  a: [{ transform: "translate3d(0%, 0%, 0) scale(1)" }, { transform: "translate3d(14%, 9%, 0) scale(1.08)" }],
  b: [{ transform: "translate3d(0%, 0%, 0) scale(1)" }, { transform: "translate3d(-12%, 11%, 0) scale(1.06)" }],
  c: [{ transform: "translate3d(0%, 0%, 0) scale(1)" }, { transform: "translate3d(10%, -12%, 0) scale(0.94)" }],
  d: [{ transform: "translate3d(0%, 0%, 0) scale(1)" }, { transform: "translate3d(-8%, -7%, 0) scale(1.1)" }],
  bandA: [{ transform: "rotate(-6deg) translate3d(0%, 0, 0)" }, { transform: "rotate(-6deg) translate3d(8%, 0, 0)" }],
  bandB: [{ transform: "rotate(7deg) translate3d(0%, 0, 0)" }, { transform: "rotate(7deg) translate3d(-8%, 0, 0)" }],
  /** Silk plates. Small travel so the loop eases back and never opens an edge. */
  flowA: [{ transform: "translate3d(0%, 0%, 0) scale(1)" }, { transform: "translate3d(3.5%, 2.2%, 0) scale(1.035)" }],
  flowB: [{ transform: "translate3d(0%, 0%, 0) scale(1)" }, { transform: "translate3d(-4%, 3%, 0) scale(1.04)" }],
  flowC: [{ transform: "translate3d(0%, 0%, 0) scale(1)" }, { transform: "translate3d(3%, -2.6%, 0) scale(1.03)" }],
};

const DRIFT_MS: Record<DriftName, number> = {
  a: 18000,
  b: 24000,
  c: 21000,
  d: 28000,
  bandA: 16000,
  bandB: 22000,
  flowA: 20000,
  flowB: 17000,
  flowC: 23000,
};

function ensureDriftCss(): void {
  if (typeof document === "undefined" || !document.head) return;
  if (document.getElementById("billboard-drift")) return;
  const style = document.createElement("style");
  style.id = "billboard-drift";
  const names = Object.keys(DRIFT_FRAMES) as DriftName[];
  const body = names
    .map((name) => {
      const [from, to] = DRIFT_FRAMES[name];
      return `@keyframes bb-drift-${name}{from{transform:${from.transform}}to{transform:${to.transform}}}`;
    })
    .join("");
  style.textContent = `${body}@media (prefers-reduced-motion:reduce){[data-bb-drift]{animation:none!important}}`;
  document.head.appendChild(style);
}

/**
 * Slow drift via the Web Animations API so React does not re-render the
 * glass. A stylesheet is the fallback when animate() is missing.
 */
function Drift({ name, style, children }: { name: DriftName; style: CSSProperties; children?: ReactNode }): JSX.Element {
  const ref = useRef<HTMLDivElement | null>(null);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const reduce =
      typeof window !== "undefined" && typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) return;
    const frames = DRIFT_FRAMES[name];
    const duration = DRIFT_MS[name];
    if (typeof node.animate === "function") {
      const anim = node.animate(frames, {
        duration,
        iterations: Infinity,
        direction: "alternate",
        easing: "ease-in-out",
        fill: "both",
      });
      return (): void => {
        anim.cancel();
      };
    }
    ensureDriftCss();
    node.style.animation = `bb-drift-${name} ${duration}ms ease-in-out infinite alternate`;
    return (): void => {
      node.style.animation = "";
    };
  }, [name]);
  return (
    <div ref={ref} data-bb-drift={name} style={style}>
      {children}
    </div>
  );
}

type BloomSpec = {
  key: string;
  drift: DriftName;
  color: string;
  opacity: number;
  blur: number;
  box: CSSProperties;
};

const BLOOM_BOX: readonly CSSProperties[] = [
  { left: "-12%", top: "-18%", width: "78%", height: "52%" },
  { right: "-18%", top: "22%", width: "70%", height: "46%" },
  { left: "8%", bottom: "-20%", width: "84%", height: "48%" },
  { left: "28%", top: "34%", width: "50%", height: "38%" },
];
const BLOOM_BLUR = [90, 100, 110, 80] as const;
const BLOOM_DRIFT: readonly DriftName[] = ["a", "b", "c", "d"];

function stageBlooms(look: BillboardLook): BloomSpec[] {
  const opacity = look.appearance === "day" ? ([0.34, 0.22, 0.2] as const) : ([0.2, 0.34, 0.16] as const);
  const colors = [look.theme.text.primary, look.theme.text.secondary, look.theme.text.primary];
  return colors.map((color, index) => ({
    key: `graphite-${index}`,
    drift: BLOOM_DRIFT[index],
    color,
    opacity: opacity[index],
    blur: BLOOM_BLUR[index],
    box: BLOOM_BOX[index],
  }));
}

const STAGE_FRAME: CSSProperties = {
  // Fixed to the viewport. An absolute stage only paints the page box, and
  // that box shrink-wraps when the host sizes from content — left and right
  // then stay host ground. Fixed covers the viewport even when an ancestor
  // clips the page.
  position: "fixed",
  inset: 0,
  zIndex: 0,
  pointerEvents: "none",
  overflow: "hidden",
};

/**
 * Baked liquid-silk plates. Dark is the teal-fold still. Day is the same
 * material in a light key. Ribbon and peach are black-backed sheets screened
 * into the field so the three stills read as one fabric. Never a hairline grid.
 */
const SILK_DARK = "data:image/jpeg;base64,";
const SILK_DAY = "data:image/jpeg;base64,";
const SILK_RIBBON = "data:image/jpeg;base64,";
const SILK_PEACH = "data:image/jpeg;base64,";
/** Soft top veil so the hero keeps a seat. The silk stays visible under it. */
const SILK_VEIL_DARK = "radial-gradient(ellipse 64% 18% at 50% 6%, rgba(0,0,0,0.38), rgba(0,0,0,0) 70%)";
const SILK_VEIL_DAY = "radial-gradient(ellipse 64% 18% at 50% 4%, rgba(255,255,255,0.42), rgba(255,255,255,0) 72%)";
/**
 * Day plate key. The daylight still holds dark pockets, so a flat wash
 * left the milky lip flashing. This lifts that black point and puts the
 * chroma back: teal, cyan, and peach on a paper base. Dark does not use it.
 */
const SILK_DAY_KEY = "contrast(0.22) brightness(1.62) saturate(2.15)";
/** Cool paper under the day plates, in case a drift edge ever clears them. */
const SILK_PAPER_DAY = "#f3f7f6";
/**
 * Studio charcoal under the dark plates. Sampled from the plate's dark mass
 * so a peek matches the silk instead of a lighter host or theme base.
 */
const SILK_INK_DARK = "#041115";
const SILK_MASK_RIBBON = "linear-gradient(90deg, rgba(0,0,0,0) 0%, rgba(0,0,0,1) 16%, rgba(0,0,0,1) 84%, rgba(0,0,0,0) 100%)";
const SILK_MASK_PEACH = "radial-gradient(72% 50% at 32% 74%, rgba(0,0,0,1) 0%, rgba(0,0,0,0) 72%)";

const SILK_IMG: CSSProperties = {
  position: "absolute",
  inset: 0,
  width: "100%",
  height: "100%",
  objectFit: "cover",
  display: "block",
  pointerEvents: "none",
};

/** Silver leaves the plates alone. Named accents rotate the whole stack. */
function silkFilter(accent: AccentName): string {
  if (accent === "silver") return "none";
  const hue = SILK_HUE[accent];
  return hue === 0 ? "saturate(1.08)" : `hue-rotate(${hue}deg) saturate(1.08)`;
}

/**
 * Graphite plus silver. Neutral blooms and a soft sheen only — no hairline lattice.
 */
function GraphiteStage({ look }: { look: BillboardLook }): JSX.Element {
  const dark = look.dark;
  const band = dark ? BAND_DARK : BAND_LIGHT;
  const scrim = dark ? SCRIM_DARK : SCRIM_LIGHT;
  return (
    <div aria-hidden style={{ ...STAGE_FRAME, background: stageGround(look) }}>
      {stageBlooms(look).map((bloom) => (
        <Drift
          key={bloom.key}
          name={bloom.drift}
          style={{
            position: "absolute",
            borderRadius: "50%",
            background: bloom.color,
            filter: `blur(${bloom.blur}px)`,
            opacity: bloom.opacity,
            pointerEvents: "none",
            ...bloom.box,
          }}
        />
      ))}
      <Drift
        name="bandA"
        style={{
          position: "absolute",
          left: "-20%",
          right: "-20%",
          top: "10%",
          height: 96,
          background: band,
          opacity: dark ? 0.42 : 0.28,
          transform: "rotate(-6deg)",
          transformOrigin: "left center",
          pointerEvents: "none",
        }}
      />
      <Drift
        name="bandB"
        style={{
          position: "absolute",
          left: "-20%",
          right: "-20%",
          top: "48%",
          height: 72,
          background: band,
          opacity: dark ? 0.34 : 0.22,
          transform: "rotate(7deg)",
          transformOrigin: "left center",
          pointerEvents: "none",
        }}
      />
      <div style={{ position: "absolute", inset: 0, background: scrim, pointerEvents: "none" }} />
    </div>
  );
}

/**
 * Color stage, and any named accent. Photographic silk, not soft blooms.
 * Dark keeps the studio plates. Day keys the daylight plate onto paper and
 * screens the ribbon and peach from the drift layer, so their black sheet
 * does not cover the light field. Those three loops stay. A named accent
 * hue-shifts the stack. Silver does not. Tiles stay neutral.
 */
function SilkStage({ look }: { look: BillboardLook }): JSX.Element {
  const dark = look.dark;
  const ground = dark ? SILK_DARK : SILK_DAY;
  // Screen lives on the image in the dark stack. That is the studio composite.
  // On day the drift transform would trap a blend on the image and paint the
  // black sheet over the paper, so the screen sits on the moving layer.
  const ribbon: CSSProperties = {
    mixBlendMode: "screen",
    opacity: dark ? 0.78 : 0.9,
    maskImage: SILK_MASK_RIBBON,
    WebkitMaskImage: SILK_MASK_RIBBON,
  };
  const peach: CSSProperties = {
    mixBlendMode: "screen",
    opacity: dark ? 0.5 : 0.62,
    maskImage: SILK_MASK_PEACH,
    WebkitMaskImage: SILK_MASK_PEACH,
  };
  return (
    <div aria-hidden style={{ ...STAGE_FRAME, isolation: "isolate", background: stageGround(look) }}>
      <div
        style={{
          position: "absolute",
          inset: "-14%",
          filter: silkFilter(look.accent),
          pointerEvents: "none",
        }}
      >
        <Drift name="flowA" style={{ position: "absolute", inset: 0 }}>
          <img
            alt=""
            src={ground}
            style={{
              ...SILK_IMG,
              objectPosition: dark ? "68% 46%" : "center",
              ...(dark ? {} : { filter: SILK_DAY_KEY }),
            }}
          />
        </Drift>
        <Drift name="flowB" style={{ position: "absolute", inset: 0, ...(dark ? {} : ribbon) }}>
          <img alt="" src={SILK_RIBBON} style={{ ...SILK_IMG, objectPosition: "center 28%", ...(dark ? ribbon : {}) }} />
        </Drift>
        <Drift name="flowC" style={{ position: "absolute", inset: 0, ...(dark ? {} : peach) }}>
          <img alt="" src={SILK_PEACH} style={{ ...SILK_IMG, objectPosition: "28% 72%", ...(dark ? peach : {}) }} />
        </Drift>
      </div>
      <div style={{ position: "absolute", inset: 0, background: dark ? SILK_VEIL_DARK : SILK_VEIL_DAY, pointerEvents: "none" }} />
    </div>
  );
}

/**
 * Graphite plus silver stays the neutral device field.
 * Color, or any named accent, drives the silk plates.
 */
function Stage(): JSX.Element {
  const look = useBillboardLook();
  const desktop = useDesktop();
  const ref = useRef<HTMLDivElement | null>(null);
  // #root is contain:paint and max-width 72rem, which traps position:fixed
  // and leaves the document ground in the side margins. On a desktop the
  // stage node is parked on the body so the plates cover the viewport. The
  // phone leaves it in the page, where the column already meets the edges.
  // The effect repeats after each commit because a render puts the node back
  // under the page.
  useEffect(() => {
    const node = ref.current;
    if (!node || typeof document === "undefined") return;
    const page = document.getElementById(LAYOUT);
    if (!desktop || !document.body) {
      if (page && node.parentElement !== page) page.insertBefore(node, page.firstChild);
      return;
    }
    document.body.insertBefore(node, document.body.firstChild);
    return () => {
      const home = document.getElementById(LAYOUT);
      if (home && node.isConnected && node.parentElement !== home) home.insertBefore(node, home.firstChild);
    };
  });
  const stage = look.stage === "color" || look.accent !== "silver" ? <SilkStage look={look} /> : <GraphiteStage look={look} />;
  return (
    <div ref={ref} style={{ display: "contents" }}>
      {stage}
    </div>
  );
}

/** Color, or any named accent, is the silk field. Graphite plus silver stays the device field. */
function silkField(look: BillboardLook): boolean {
  return look.stage === "color" || look.accent !== "silver";
}

/**
 * Ground behind the plates or blooms. Silk day is the paper key. Silk dark
 * is the studio charcoal. Graphite uses the device base. The page, the stage,
 * and the document share it, so a gutter cannot flash theme white.
 */
function stageGround(look: BillboardLook): string {
  if (!silkField(look)) return look.bg;
  return look.dark ? SILK_INK_DARK : SILK_PAPER_DAY;
}

/**
 * Paint the canvas document with the stage ground and drop the default
 * body margin so rubber-band overscroll and the viewport edge match the
 * field instead of flashing theme white.
 */
function useStageDocument(ground: string): void {
  useEffect(() => {
    if (typeof document === "undefined") return;
    const html = document.documentElement;
    const body = document.body;
    if (!html || !body) return;
    const prevHtml = html.style.cssText;
    const prevBody = body.style.cssText;
    html.style.background = ground;
    body.style.background = ground;
    html.style.margin = "0";
    body.style.margin = "0";
    html.style.padding = "0";
    body.style.padding = "0";
    html.style.minHeight = "100%";
    body.style.minHeight = "100%";
    html.style.width = "100%";
    body.style.width = "100%";
    // 100dvw can be a hair wider than the layout viewport. Clip that
    // instead of opening a horizontal scrollport beside the silk.
    html.style.overflowX = "clip";
    body.style.overflowX = "clip";
    return () => {
      html.style.cssText = prevHtml;
      body.style.cssText = prevBody;
    };
  }, [ground]);
}

/**
 * Host narrow cutoff. At this width and above, the column is the desktop
 * measure and the silk is pulled out to the viewport. Below it, the phone
 * column stays exactly as it shipped.
 */
const DESKTOP_QUERY = "(min-width: 480px)";
/**
 * Owner markup, center of one red stroke to the center of the other.
 * Header, tiles, and icon chips share this desktop measure.
 */
const DESKTOP_COLUMN_PX = 445;

function desktopNow(): boolean {
  return typeof window !== "undefined" && typeof window.matchMedia === "function" && window.matchMedia(DESKTOP_QUERY).matches;
}

function useDesktop(): boolean {
  const [desktop, setDesktop] = useState(desktopNow);
  useEffect(() => {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") return;
    const mq = window.matchMedia(DESKTOP_QUERY);
    const onChange = (): void => setDesktop(mq.matches);
    onChange();
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return desktop;
}

/**
 * The host paints #root at max-width 72rem with contain:paint, which traps
 * position:fixed and leaves the document ground in the side margins. On a
 * desktop the root is opened to the viewport and lifted above the stage, so
 * the plates can sit on the body and still show through the column.
 */
function useDesktopStageHost(desktop: boolean): void {
  useEffect(() => {
    if (!desktop || typeof document === "undefined") return;
    const root = document.getElementById("root");
    if (!root) return;
    const keys = ["max-width", "width", "margin", "background-color", "overflow-x", "z-index", "position"] as const;
    root.style.setProperty("max-width", "none", "important");
    root.style.setProperty("width", "100%", "important");
    root.style.setProperty("margin", "0", "important");
    root.style.setProperty("background-color", "transparent", "important");
    root.style.setProperty("overflow-x", "clip", "important");
    root.style.setProperty("position", "relative", "important");
    root.style.setProperty("z-index", "1", "important");
    return () => {
      for (const key of keys) root.style.removeProperty(key);
    };
  }, [desktop]);
}

function pageStyle(look: BillboardLook, desktop: boolean): CSSProperties {
  const ground = stageGround(look);
  return {
    position: "relative",
    // Phone: 100dvw plus the breakout margins, so a shrink-wrapped host still
    // reaches the viewport. Desktop: the root is already the viewport, and a
    // dvw box would open a horizontal scrollport beside the silk.
    width: desktop ? "100%" : "100dvw",
    maxWidth: desktop ? "100%" : "100dvw",
    minWidth: desktop ? 0 : "100dvw",
    marginLeft: desktop ? 0 : "calc(50% - 50dvw)",
    marginRight: desktop ? 0 : "calc(50% - 50dvw)",
    // 100% fills a sized host. 100dvh covers a short page when the parent
    // height is auto and percentage min-height collapses.
    minHeight: "max(100%, 100dvh)",
    // clip does not force a vertical scrollport, so the column still scrolls
    // with the document.
    overflowX: "clip",
    // Desktop silk is positioned on the body, behind this box. An opaque
    // page ground would hide it. The phone still paints the ground here.
    background: desktop ? "transparent" : ground,
    color: look.ink,
    fontFamily: look.theme.font.family,
    fontSynthesis: "none",
    WebkitFontSmoothing: "antialiased",
    MozOsxFontSmoothing: "grayscale",
    boxSizing: "border-box",
  };
}

/**
 * Phone: the column is the viewport, inset 16px or the safe area.
 * Desktop: the column is the red-line measure, centered on the silk.
 * Header, tiles, and icon chips share whichever measure is active.
 */
function bandStyle(desktop: boolean): CSSProperties {
  return {
    position: "relative",
    zIndex: 1,
    width: "100%",
    maxWidth: desktop ? DESKTOP_COLUMN_PX : "100%",
    margin: "0 auto",
    boxSizing: "border-box",
    paddingTop: "max(24px, env(safe-area-inset-top, 0px))",
    paddingRight: desktop ? 0 : "max(clamp(16px, 2.5vw, 40px), env(safe-area-inset-right, 0px))",
    paddingBottom: "max(28px, env(safe-area-inset-bottom, 0px))",
    paddingLeft: desktop ? 0 : "max(clamp(16px, 2.5vw, 40px), env(safe-area-inset-left, 0px))",
    display: "flex",
    flexDirection: "column",
    alignItems: "stretch",
    gap: 22,
    minWidth: 0,
  };
}

const FORE: CSSProperties = { position: "relative", zIndex: 1, minWidth: 0 };

/** Square glass chip. The pill dial turns it into a circle. 44px keeps the touch target. */
