function linkHost(href: string): string {
  const trimmed = href.trim();
  if (trimmed.length === 0 || trimmed.startsWith("__")) return "";
  const withoutScheme = trimmed.replace(/^[a-z][a-z0-9+.-]*:\/\//i, "");
  const hostPort = withoutScheme.split(/[/?#]/)[0] ?? "";
  return (hostPort.split(":")[0] ?? "").replace(/^www\./i, "").toLowerCase();
}

function linkKind(link: Link): LinkKind {
  const href = filled(link.href);
  if (/^mailto:/i.test(href)) return "email";
  const host = linkHost(href);
  if (host.length > 0) {
    for (let i = 0; i < HOST_KIND.length; i++) {
      const domain = HOST_KIND[i][0];
      const kind = HOST_KIND[i][1];
      if (host === domain || host.endsWith(`.${domain}`)) return kind;
    }
  }
  const words = `${filled(link.label)} ${filled(link.display)}`.toLowerCase().split(/[^a-z0-9]+/);
  for (let i = 0; i < words.length; i++) {
    const kind = LABEL_KIND[words[i] ?? ""];
    if (kind) return kind;
  }
  return "site";
}

/** Kind plus the handle, for the chip's aria-label and title. */
function linkName(link: Link, kind: LinkKind): string {
  const kindName = KIND_NAME[kind];
  const label = filled(link.label);
  const display = filled(link.display);
  const href = filled(link.href);
  const handle = display.length > 0 ? display : label.length > 0 && LABEL_KIND[label.toLowerCase().replace(/[^a-z0-9]+/g, "")] !== kind ? label : "";
  if (handle.length > 0 && handle.toLowerCase() !== kindName.toLowerCase()) return `${kindName}, ${handle}`;
  if (label.length > 0) return kindName;
  if (href.length > 0) return `${kindName}, ${href}`;
  return kindName;
}

function LinkGlyph({ kind }: { kind: LinkKind }): JSX.Element {
  return (
    <svg aria-hidden width={20} height={20} viewBox="0 0 24 24" style={{ display: "block", flexShrink: 0 }}>
      <path fill="currentColor" d={GLYPH[kind]} />
    </svg>
  );
}

function InstallTile({ bot }: { bot: Bot }): JSX.Element {
  const look = useBillboardLook();
  const theme = look.theme;
  const ring = useFocusRing();
  const name = filled(bot.name);
  const desc = filled(bot.desc);
  const icon = filled(bot.src);
  return (
    <GlassPane
      kind="tile"
      href={filled(bot.href)}
      focused={ring.focused}
      onFocus={ring.onFocus}
      onBlur={ring.onBlur}
      contentStyle={{
        display: "flex",
        flexDirection: "column",
        alignItems: "stretch",
        gap: 14,
        width: "100%",
        maxWidth: "100%",
        minWidth: 0,
        boxSizing: "border-box",
        padding: 18,
      }}
      children={[
        <div key="row" style={{ display: "flex", alignItems: "center", gap: 14, width: "100%", minWidth: 0 }}>
          <div style={iconWell(64, 16, look)}>
            {icon.length > 0 ? <Image src={icon} alt={name.length > 0 ? `${name} icon` : "Bot icon"} width={64} height={64} fit="cover" /> : null}
          </div>
          {name.length > 0 ? (
            <p
              style={{
                ...theme.font.heading1,
                ...FORE,
                fontFamily: theme.font.family,
                color: look.glassInk,
                // 22px floor: a title beside the 64px icon stays inside a 320–390px column. Desktop still caps at 30.
                fontSize: "clamp(22px, 5.6vw, 30px)",
                lineHeight: 1.05,
                fontWeight: theme.weight.semibold,
                letterSpacing: "-0.03em",
                textTransform: "none",
                textShadow: "var(--bb-ink-shadow)",
                transition: `text-shadow ${MOTION}`,
                margin: 0,
                flex: "1 1 auto",
                minWidth: 0,
                maxWidth: "100%",
                overflowWrap: "anywhere",
                wordBreak: "break-word",
              }}
            >
              {name}
            </p>
          ) : null}
        </div>,
        desc.length > 0 ? (
          <p
            key="desc"
            style={{
              ...theme.font.body1,
              ...FORE,
              fontFamily: theme.font.family,
              color: look.glassInk,
              fontSize: 14,
              lineHeight: 1.35,
              fontWeight: theme.weight.medium,
              letterSpacing: "0",
              textTransform: "none",
              textShadow: "var(--bb-ink-shadow)",
              transition: `text-shadow ${MOTION}`,
              margin: 0,
              maxWidth: "100%",
              overflowWrap: "anywhere",
              wordBreak: "break-word",
            }}
          >
            {desc}
          </p>
        ) : null,
      ]}
    />
  );
}

function MiniLink({ link }: { link: Link }): JSX.Element {
  const look = useBillboardLook();
  const ring = useFocusRing();
  const href = filled(link.href);
  const kind = linkKind(link);
  const name = linkName(link, kind);
  return (
    <GlassPane
      kind="chip"
      href={href}
      name={name}
      focused={ring.focused}
      onFocus={ring.onFocus}
      onBlur={ring.onBlur}
      frame={{
        width: CHIP_SIZE,
        height: CHIP_SIZE,
        minWidth: CHIP_SIZE,
        minHeight: CHIP_SIZE,
        flex: "0 0 auto",
        alignItems: "center",
        justifyContent: "center",
      }}
      contentStyle={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        width: CHIP_SIZE,
        height: CHIP_SIZE,
        boxSizing: "border-box",
        padding: 0,
        color: look.glassInk,
      }}
      children={<LinkGlyph kind={kind} />}
    />
  );
}

export default function App(): JSX.Element {
  const look = useBillboardLook();
  const desktop = useDesktop();
  useDesktopStageHost(desktop);
  useStageDocument(stageGround(look));
  const theme = look.theme;
  const handle = atHandle(HANDLE);
  const hero = splitTrailingEmoji(DISPLAY_NAME);
  const bio = filled(BIO);
  const footer = filled(FOOTER);
  const avatar = filled(AVATAR);
  const shownBots = bots.filter((bot) => filled(bot.name).length > 0 || filled(bot.desc).length > 0 || filled(bot.href).length > 0 || filled(bot.src).length > 0);
  const shownLinks = links.filter((link) => filled(link.label).length > 0 || filled(link.display).length > 0 || filled(link.href).length > 0);
  const showHero = hero.text.length > 0 || hero.clusters.length > 0;
  const dark = look.dark;
  return (
    <div id={LAYOUT} style={pageStyle(look, desktop)}>
      <Stage />
      <div style={bandStyle(desktop)}>
        <header
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            textAlign: "center",
            gap: 0,
            width: "100%",
            maxWidth: "100%",
            minWidth: 0,
          }}
        >
          <div style={avatarRing(look)}>
            {avatar.length > 0 ? (
              <Image src={avatar} alt={hero.text.length > 0 ? `${hero.text} avatar` : "Profile avatar"} width={AVATAR_SIZE} height={AVATAR_SIZE} fit="cover" />
            ) : null}
          </div>
          {showHero ? (
          <h1
            style={{
              fontFamily: theme.font.family,
              color: look.glassInk,
              fontSize: "clamp(46px, 13vw, 72px)",
              lineHeight: 0.96,
              fontWeight: theme.weight.semibold,
              letterSpacing: "-0.034em",
              textTransform: "none",
              textAlign: "center",
              textShadow: dark ? SOFT_SHADOW_DARK : SOFT_SHADOW_LIGHT,
              margin: "10px 0 0",
              width: "100%",
              maxWidth: "100%",
              minWidth: 0,
              boxSizing: "border-box",
              overflowWrap: "anywhere",
              wordBreak: "break-word",
            }}
          >
            {hero.text.length > 0 ? hero.text : null}
            {hero.clusters.map((cluster, index) => (
              <span key={`hero-emoji-${index}`} style={heroEmojiStyle(index, hero.text.length > 0, dark ? SILVER : look.ink)}>
                {cluster}
              </span>
            ))}
          </h1>
          ) : null}
          {handle.length > 0 ? (
            <p
              style={{
                fontFamily: theme.font.family,
                color: look.ink,
                fontSize: 15,
                lineHeight: 1.25,
                fontWeight: theme.weight.medium,
                letterSpacing: "0",
                textAlign: "center",
                textShadow: dark ? SOFT_SHADOW_DARK : SOFT_SHADOW_LIGHT,
                margin: "4px 0 0",
                width: "100%",
                maxWidth: "100%",
                minWidth: 0,
                overflowWrap: "anywhere",
                wordBreak: "break-word",
              }}
            >
              {handle}
            </p>
          ) : null}
          {bio.length > 0 ? (
          <p
            style={{
              fontFamily: theme.font.family,
              color: look.ink,
              fontSize: 15,
              lineHeight: 1.45,
              fontWeight: theme.weight.regular,
              letterSpacing: "0",
              textTransform: "none",
              textAlign: "center",
              textShadow: dark ? SOFT_SHADOW_DARK : SOFT_SHADOW_LIGHT,
              margin: "8px 0 0",
              width: "100%",
              maxWidth: "100%",
              minWidth: 0,
              whiteSpace: "pre-wrap",
              overflowWrap: "anywhere",
              wordBreak: "break-word",
            }}
          >
            {bio}
          </p>
          ) : null}
        </header>

        {shownBots.length > 0 ? (
          <section style={{ display: "flex", flexDirection: "column", gap: 14, width: "100%", maxWidth: "100%", minWidth: 0 }}>
            {shownBots.map((bot, index) => (
              <InstallTile key={`${bot.href}-${index}`} bot={bot} />
            ))}
          </section>
        ) : null}

        {shownLinks.length > 0 ? (
          <nav
            style={{
              display: "flex",
              flexWrap: "wrap",
              justifyContent: "center",
              alignItems: "center",
              alignContent: "center",
              gap: 10,
              width: "100%",
              maxWidth: "100%",
              minWidth: 0,
            }}
          >
            {shownLinks.map((link, index) => (
              <MiniLink key={`${link.href}-${link.label}-${index}`} link={link} />
            ))}
          </nav>
        ) : null}

        {footer.length > 0 ? (
        <p
          style={{
            fontFamily: theme.font.family,
            color: look.ink,
            fontSize: 12,
            lineHeight: 1.4,
            fontWeight: theme.weight.medium,
            letterSpacing: "0",
            textTransform: "none",
            textShadow: dark ? SOFT_SHADOW_DARK : SOFT_SHADOW_LIGHT,
            textAlign: "center",
            margin: 0,
            width: "100%",
            maxWidth: "100%",
            minWidth: 0,
            overflowWrap: "anywhere",
            wordBreak: "break-word",
          }}
        >
          {footer}
        </p>
        ) : null}
      </div>
    </div>
  );
}
